import { readFileSync, writeFileSync, mkdtempSync, symlinkSync } from "node:fs"
import { execFileSync } from "node:child_process"
import { createHash } from "node:crypto"
import { tmpdir } from "node:os"
import { dirname, join, resolve } from "node:path"
import { gunzipSync } from "node:zlib"
import { deepStrictEqual, strictEqual } from "node:assert"
const repo = resolve(process.argv[2] ?? process.cwd())
const proof = JSON.parse(readFileSync(join(repo, "docs/benchmarks/reference-drc-component-once-proof.json"), "utf8"))
const checkerPath = proof.sources.checker
const sourceDir = dirname(join(repo, checkerPath))
const work = mkdtempSync(join(tmpdir(), "reference-component-once-"))
symlinkSync(join(repo, "node_modules"), join(work, "node_modules"))
const hash = (text: string | Uint8Array) => createHash("sha256").update(text).digest("hex")
const controls: any[] = []
for (const kind of ["native", "candidate"]) {
 const source = kind === "native"
  ? execFileSync("git", ["show", `${proof.sources.nativeRevision}:${checkerPath}`], { cwd: repo, encoding: "utf8" })
  : readFileSync(join(repo, checkerPath), "utf8")
 strictEqual(hash(source), proof.sourceHashes[`${kind}Checker`])
 const dir = join(work, kind)
 execFileSync("mkdir", ["-p", dir])
 const filename = join(dir, "checker.ts")
 writeFileSync(filename, source)
 execFileSync("patch", ["--batch", "-p0"], { cwd: dir, input: proof.reproduction.instrumentationPatches[kind] })
 const instrumented = readFileSync(filename, "utf8").replace(/from\s+"(\.[^"]+)"/g, (_match, spec) => `from ${JSON.stringify(resolve(sourceDir, spec))}`)
 writeFileSync(filename, instrumented)
 controls.push(await import(filename))
}
const { getDrcErrors } = await import(join(repo, "lib/testing/getDrcErrors.ts"))
const { initializeReferenceDrcRuntime } = await import(join(repo, "lib/autorouter-pipelines/AutoroutingPipeline9_Parallel/authoritative-drc-fork/initializeReferenceDrcRuntime.ts"))
const { checkViaTraceClearanceWithLazyCenters } = await import(join(repo, "lib/autorouter-pipelines/AutoroutingPipeline9_Parallel/authoritative-drc-fork/checkViaTraceClearanceWithLazyCenters.ts"))
await initializeReferenceDrcRuntime()
const fixtureBytes = readFileSync(join(repo, proof.sources.fixture))
strictEqual(hash(fixtureBytes), proof.sourceHashes.fixture)
const captures = JSON.parse(gunzipSync(fixtureBytes).toString())
const checkers = controls.map((control) => control.createPrivatelyMemoizedTraceContinuityChecker())
const totals: any = { originalGraphQueries: 0, candidateGraphQueries: 0, originalGraphMembers: 0, candidateGraphMembers: 0 }
const unchanged: any = { padAdjacencyVisits: 0, touchingTraceNeighborVisits: 0, componentMembershipTests: 0, components: 0, filteredMemberReferences: 0 }
const rows: any[] = []
for (const capture of captures.records) {
 const states = controls.map((control, index) => {
  control.resetPartitionCensus()
  const result = getDrcErrors(structuredClone(capture.circuitJson), {
   ...capture.options, traceContinuityChecker: checkers[index],
   viaTraceChecker: (circuit: any, options: any) => checkViaTraceClearanceWithLazyCenters(circuit, { ...options, enableAxisRejection: true, enableConnectivityMemo: true }),
  })
  deepStrictEqual(JSON.parse(JSON.stringify(result)), capture.expected)
  return structuredClone(control.partitionCensus)
 })
 const withoutTraces = ({ traces, ...rest }: any) => rest
 deepStrictEqual(withoutTraces(states[0]), withoutTraces(states[1]))
 strictEqual(states[0].expectedMemo, true)
 strictEqual(states[0].traces.length, states[1].traces.length)
 const row: any = { number: capture.number, errors: capture.expected.errors.length }
 for (let index = 0; index < states[0].traces.length; index++) {
  const native = states[0].traces[index], candidate = states[1].traces[index]
  const withoutGraphCounts = ({ graphQueries, graphMembers, ...rest }: any) => rest
  deepStrictEqual(withoutGraphCounts(native), withoutGraphCounts(candidate))
  for (const key of ["padAdjacencyVisits", "touchingTraceNeighborVisits", "componentMembershipTests"]) unchanged[key] += native[key]
  unchanged.components += native.componentWitnesses.length
  for (const witness of native.componentWitnesses) {
   strictEqual(witness.aliasesExact, true)
   unchanged.filteredMemberReferences += witness.memberIndexes.length
  }
 }
 for (const [prefix, state] of [["original", states[0]], ["candidate", states[1]]] as const) {
  for (const [suffix, counter] of [["GraphQueries", "graphQueries"], ["GraphMembers", "graphMembers"]]) {
   row[prefix + suffix] = state.traces.reduce((sum: number, trace: any) => sum + trace[counter], 0)
   totals[prefix + suffix] += row[prefix + suffix]
  }
 }
 rows.push(row)
}
deepStrictEqual(totals, proof.operationCensus.totals)
deepStrictEqual(unchanged, proof.operationCensus.unchangedAdjacencyAndAliasWitnessCounts)
writeFileSync(join(work, "replay-result.json"), JSON.stringify({ allSavedErrorsExact: true, allMemoAndConsumedWorkExact: true, totals, unchanged, rows }, null, 2) + "\n")
console.log(JSON.stringify({ records: rows.length, allSavedErrorsExact: true, totals, unchanged, output: join(work, "replay-result.json") }))

